// Player-facing Decimator and BAF resolution helpers.
//
// A Decimator win has NO player action. Since audit 92a1358d0 the Decimator is
// a shared-dice craps battle: keepers settle it through the public
// settleDecimatorWinners progress path (and mineFlip's Decimator leg), which
// plays every heads entry, ranks the best stack x peak and credits each winner
// as claimable ETH or half whale passes. BAF normally resolves atomically during
// the level transition; the only player-callable BAF resolution is WWXRP
// consolation after a skipped x10 round.

import { CHAIN, CONTRACTS } from './chain-config.js';
import { sharedReadProvider } from './read-provider.js';
import { sendTx, getProvider, ethers } from './contracts.js';
import { requireStaticCall } from './static-call.js';
import { decodeRevertReason } from './reason-map.js';
import { getActingAddress } from './store.js';
import { flipFromChain } from './token-units.js';

const BAF_RESOLUTION_ABI = [
  'function bafConsolationOf(address player, uint24 lvl) external view returns (uint256)',
  'function claimBafConsolation(address player, uint24 lvl) external',
  'event BafConsolationClaimed(address indexed player, uint24 indexed lvl, uint256 score, uint256 wwxrpAmount)',
  'error NothingToClaim()',
];
const ENTRIES_PER_TICKET = 4n;

let _bafFactory = null;
let _entryReader = null;
let _readProvider = null;

/** Test-only seams (`entry` replaces the player-entry lookup). */
export function __setResolutionFactoriesForTest({ baf, entry } = {}) {
  _bafFactory = typeof baf === 'function' ? baf : null;
  _entryReader = typeof entry === 'function' ? entry : null;
}

/** Test-only reset. */
export function __resetResolutionFactoriesForTest() {
  _bafFactory = null;
  _entryReader = null;
  _readProvider = null;
}

function _readerProvider() {
  if (!_readProvider) {
    _readProvider = sharedReadProvider();  // C15: shared batched read stream
  }
  // These are permissionless, explicit-player reads. Keep expected claim
  // reverts off the injected wallet's console; the wallet remains a fallback
  // only when no public reader is configured.
  return _readProvider || getProvider();
}

function _bafContract(runner) {
  if (_bafFactory) return _bafFactory(runner);
  return new ethers.Contract(CONTRACTS.JACKPOTS, BAF_RESOLUTION_ABI, runner);
}

function _errorName(error) {
  return error?.revert?.name || error?.errorName || null;
}

function _resolutionError(error, fallback) {
  const name = _errorName(error);
  const local = name === 'NothingToClaim'
    ? {
        code: 'NothingToClaim',
        userMessage: 'This BAF consolation was already claimed or is no longer available.',
        recoveryAction: 'The resolution display will refresh automatically.',
      }
    : null;
  const decoded = local || decodeRevertReason(error);
  const wrapped = new Error(decoded.userMessage || fallback);
  wrapped.code = decoded.code;
  wrapped.userMessage = decoded.userMessage;
  wrapped.recoveryAction = decoded.recoveryAction;
  wrapped.cause = error;
  return wrapped;
}

export function isDecimatorResolutionLevel(level) {
  const lvl = Number(level);
  if (!Number.isInteger(lvl) || lvl <= 0) return false;
  const mod100 = lvl % 100;
  return mod100 === 0 || (lvl % 10 === 5 && mod100 !== 95);
}

/**
 * Should the latest finished, undismissed Decimator draw be surfaced?
 *
 * A resolved draw is now a real fullscreen receipt, not an empty historical
 * action. Keep that latest receipt available until the player opens/clears it;
 * decimatorResolutionLevel() naturally replaces it when the next Decimator
 * resolves. Claimable payouts remain independently actionable as before.
 *
 * @param {{closed?: boolean, seen?: boolean}} args
 * @returns {boolean}
 */
export function decimatorFinalIsNews({ closed, seen } = {}) {
  return closed === true && seen !== true;
}

/**
 * Keep a player's latest BAF receipt available when indexing finishes after
 * the exact x10 boundary. Everyone may watch it at the boundary; afterwards
 * only a wallet with participation/payout evidence carries the receipt forward
 * through the rest of that same ten-level bracket.
 */
export function bafFinalIsNews({ closed, seen, currentLevel, level, participated } = {}) {
  if (closed !== true || seen === true) return false;
  const current = Number(currentLevel);
  const target = Number(level);
  return (Number.isInteger(current) && Number.isInteger(target) && current === target)
    || participated === true;
}

/**
 * Pick the round a live player-resolution display should show.
 *
 * During x4/x99 the burn targets the following x5/x00 round. Otherwise the
 * newest eligible level at or below the current level remains on screen. The
 * level-5 fallback gives a pre-game visitor a useful upcoming target.
 */
export function decimatorResolutionLevel(currentLevel, windowOpen = false) {
  const lvl = Number(currentLevel);
  if (!Number.isInteger(lvl) || lvl < 0) return null;
  const mod100 = lvl % 100;
  const deterministicWindow = (lvl % 10 === 4 && mod100 !== 94) || mod100 === 99;
  // Once the target level has actually started, it outranks a stale indexed
  // `decWindowOpen` latch from x4/x99. Advancing to level 15 while that flag
  // still reads true must resolve level 15, not incorrectly probe level 16.
  if (isDecimatorResolutionLevel(lvl)) return lvl;
  if (windowOpen || deterministicWindow) return lvl + 1;

  for (let candidate = lvl; candidate > 0; candidate -= 1) {
    if (isDecimatorResolutionLevel(candidate)) return candidate;
  }
  return 5;
}

/** Latest BAF bracket, or level 10 while the first bracket is accumulating. */
export function bafResolutionLevel(currentLevel) {
  const lvl = Number(currentLevel);
  if (!Number.isInteger(lvl) || lvl < 0) return null;
  return lvl < 10 ? 10 : Math.floor(lvl / 10) * 10;
}

/**
 * BAF bracket receiving newly settled winning FLIP payouts right now.
 *
 * Coinflip records against `_bafBracketLevel(currentLevel + 1)`, so the x10
 * boundary starts the following decade's bracket instead of adding to the
 * bracket that just resolved.
 */
export function activeBafScoreLevel(currentLevel) {
  const lvl = Number(currentLevel);
  if (!Number.isInteger(lvl) || lvl < 0) return null;
  return Math.ceil((lvl + 1) / 10) * 10;
}

function _smallInt(value) {
  if (value == null || value === '') return null;
  const n = Number(value);
  return Number.isInteger(n) && n >= 0 ? n : null;
}

/**
 * A player's Decimator entry for one event, or null for a non-resolution level:
 * `{level, entryId, stack, chips, phase, roundStatus, coin, peak, winner, champion,
 * claimed, ethAmount, halfPasses, entrants, winners}`. `entryId` is null without an
 * entry; `coin` is 'heads'/'tails' once the event is sealed; `claimed` means the
 * keepers already paid it.
 */
export async function readDecimatorEntry({ player, level } = {}) {
  const lvl = Number(level);
  if (!player || !isDecimatorResolutionLevel(lvl)) return null;
  if (_entryReader) return _entryReader({ player, level: lvl });
  const owner = String(player).toLowerCase();
  const { fetchJSON } = await import('./api.js');
  const row = await fetchJSON(`/player/${owner}/decimator?level=${lvl}`);
  const coin = row?.coin === 'heads' || row?.coin === 'tails' ? row.coin : null;
  return {
    level: lvl,
    entryId: row?.entryId == null ? null : String(row.entryId),
    stack: String(row?.stack ?? '0'),
    chips: _smallInt(row?.chips),
    phase: _smallInt(row?.phase) ?? 0,
    roundStatus: String(row?.roundStatus || ''),
    coin,
    peak: row?.peak == null ? null : String(row.peak),
    winner: row?.winner === true,
    champion: row?.champion === true,
    claimed: row?.claimed === true,
    ethAmount: String(row?.ethAmount ?? '0'),
    halfPasses: String(row?.halfPasses ?? '0'),
    entrants: _smallInt(row?.entrants),
    winners: _smallInt(row?.winners),
  };
}

/** True when `entry` placed among its event's paid winners. */
export function decimatorEntryWinning(entry) {
  return Boolean(entry) && entry.entryId != null && entry.winner === true;
}

/**
 * Where a player's Decimator event stands. There is no claim to simulate, so
 * this is a pure read of the entry:
 *   - 'pending'  the event has not been ranked, and the entry is still in it;
 *   - 'lost'     no entry, a tails coin, or a heads run outside the winners;
 *   - 'queued'   a winner the keepers have not paid yet; it settles automatically;
 *   - 'claimed'  the keepers paid it;
 *   - 'unknown'  the read failed.
 */
export async function readDecimatorClaimState({ player, level } = {}) {
  if (!player || !isDecimatorResolutionLevel(level)) {
    return { state: 'unknown', errorName: null };
  }
  let entry;
  try { entry = await readDecimatorEntry({ player, level }); } catch (_e) {
    return { state: 'unknown', errorName: null };
  }
  if (!entry) return { state: 'unknown', errorName: null };
  if (entry.phase === 0) return { state: 'pending', errorName: null };
  if (entry.entryId == null || entry.coin === 'tails') return { state: 'lost', errorName: null };
  if (entry.phase === 1) return { state: 'pending', errorName: null };
  if (!decimatorEntryWinning(entry)) return { state: 'lost', errorName: null };
  if (entry.claimed) return { state: 'claimed', errorName: null };
  return { state: 'queued', errorName: null };
}

/** Exact WWXRP consolation still claimable for a skipped BAF bracket. */
export async function readBafConsolation({ player, level } = {}) {
  const lvl = Number(level);
  if (!player || !Number.isInteger(lvl) || lvl <= 0 || lvl % 10 !== 0) return null;
  try {
    // WWXRP: whole tokens on chain since audit b05ea7c50; token wei here.
    return flipFromChain(await _bafContract(_readerProvider()).bafConsolationOf(player, lvl));
  } catch (_e) {
    return null;
  }
}

/** Permissionlessly mint a skipped bracket's consolation to `player`. */
export async function claimBafConsolation({ player, level } = {}) {
  const target = player || getActingAddress();
  const lvl = Number(level);
  if (!target) throw new Error('Connect a wallet first.');
  if (!Number.isInteger(lvl) || lvl <= 0 || lvl % 10 !== 0) {
    throw new Error('Invalid BAF level.');
  }

  const provider = getProvider();
  const signer = provider ? await provider.getSigner() : null;
  if (signer) {
    const sim = await requireStaticCall(
      _bafContract(signer),
      'claimBafConsolation',
      [target, lvl],
      signer,
    );
    if (!sim.ok) throw _resolutionError(sim.error, 'BAF consolation is unavailable.');
  }

  try {
    const receipt = await sendTx(
      (freshSigner) => _bafContract(freshSigner).claimBafConsolation(target, lvl),
      `Claim BAF consolation for level ${lvl}`,
    );
    return { receipt };
  } catch (error) {
    if (_errorName(error)) throw _resolutionError(error, 'BAF consolation claim failed.');
    throw error;
  }
}

/** Aggregate one player's indexed BAF ETH and whole-ticket awards at a level. */
export function summarizeBafAwards(wins, level) {
  const lvl = Number(level);
  let eth = 0n;
  let ticketEntries = 0n;
  for (const row of Array.isArray(wins) ? wins : []) {
    const kind = String(row?.awardType || '');
    const rowLevel = Number(row?.level);
    const sourceLevel = Number(row?.sourceLevel);
    const matchesRound = rowLevel === lvl
      || (kind === 'tickets_baf' && (sourceLevel === lvl || sourceLevel === lvl + 1));
    if (!matchesRound) continue;
    try {
      if (kind === 'eth_baf') eth += BigInt(row?.amount ?? 0);
      // JackpotTicketWin.entryCount is stored verbatim by the current indexer.
      // Four on-chain entries are one complete player-facing ticket.
      if (kind === 'tickets_baf') ticketEntries += BigInt(row?.amount ?? 0);
    } catch (_e) { /* malformed indexed row: ignore just that award */ }
  }
  return { eth, tickets: ticketEntries / ENTRIES_PER_TICKET };
}
